import prisma from '@/lib/prisma';
import { auth } from '@/auth';
import TestimonialsManager from '@/components/admin/testimonials-manager';

export const dynamic = 'force-dynamic';

// Phase 2 — owner-facing ratings. Reuses the admin TestimonialsManager UI pointed at the
// owner-scoped /api/ratings endpoint. Owner sees ONLY their own ratings.
export default async function OwnerRatingPage() {
  const s = await auth();
  const items = await prisma.testimonial.findMany({
    where: { userId: s.user.id },
    orderBy: [{ order: 'asc' }, { createdAt: 'desc' }],
  });
  const data = items.map((t) => ({ id: t.id, name: t.name, text: t.text, rating: t.rating, active: t.active, order: t.order }));
  return (
    <div className="space-y-6">
      <div>
        <h1 className="font-serif text-3xl font-bold">My Ratings</h1>
        <p className="text-muted-foreground mt-1">Create and manage your own rating/testimonial. Only you can see and edit these.</p>
      </div>
      <TestimonialsManager initial={data} endpoint="/api/ratings" />
    </div>
  );
}
